import json
import os
import time
import uuid
from typing import Any, Dict, List, Optional

import boto3


class CloudWatchCorrelationLogger:
    def __init__(
        self,
        log_group_name: str,
        log_stream_name: Optional[str] = None,
        region_name: Optional[str] = None,
    ) -> None:
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name or f"app-{uuid.uuid4().hex}"
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")

        self.client = boto3.client("logs", region_name=self.region_name)
        self.sequence_token: Optional[str] = None

        self._ensure_log_group()
        self._ensure_log_stream()
        self._load_sequence_token()

    def _ensure_log_group(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass

    def _ensure_log_stream(self) -> None:
        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass

    def _load_sequence_token(self) -> None:
        response = self.client.describe_log_streams(
            logGroupName=self.log_group_name,
            logStreamNamePrefix=self.log_stream_name,
            limit=1,
        )
        streams = response.get("logStreams", [])
        if streams:
            self.sequence_token = streams[0].get("uploadSequenceToken")

    def write_events(
        self,
        correlation_id: str,
        events: List[Dict[str, Any]],
        level: str = "INFO",
        service: str = "application",
    ) -> Dict[str, Any]:
        timestamp_ms = int(time.time() * 1000)
        log_events = []
        for idx, event in enumerate(events):
            payload = {
                "correlation_id": correlation_id,
                "level": level,
                "service": service,
                "event_index": idx,
                "message": event.get("message", ""),
                "event": event,
                "timestamp": timestamp_ms,
            }
            log_events.append(
                {
                    "timestamp": timestamp_ms + idx,
                    "message": json.dumps(payload, separators=(",", ":"), ensure_ascii=False),
                }
            )

        kwargs: Dict[str, Any] = {
            "logGroupName": self.log_group_name,
            "logStreamName": self.log_stream_name,
            "logEvents": log_events,
        }
        if self.sequence_token:
            kwargs["sequenceToken"] = self.sequence_token

        response = self.client.put_log_events(**kwargs)
        self.sequence_token = response.get("nextSequenceToken", self.sequence_token)
        return response

    def query_by_correlation_id(
        self,
        correlation_id: str,
        start_time_ms: Optional[int] = None,
        end_time_ms: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        if start_time_ms is None:
            start_time_ms = int((time.time() - 3600) * 1000)
        if end_time_ms is None:
            end_time_ms = int(time.time() * 1000)

        query = (
            f'fields @timestamp, @message '
            f'| filter correlation_id = "{correlation_id}" '
            f'| sort @timestamp asc'
        )

        start_response = self.client.start_query(
            logGroupName=self.log_group_name,
            startTime=start_time_ms // 1000,
            endTime=end_time_ms // 1000,
            queryString=query,
        )
        query_id = start_response["queryId"]

        for _ in range(60):
            result = self.client.get_query_results(queryId=query_id)
            status = result.get("status")
            if status in ("Complete", "Failed", "Cancelled", "Timeout"):
                if status != "Complete":
                    return []
                rows = []
                for row in result.get("results", []):
                    item = {field["field"]: field.get("value") for field in row}
                    rows.append(item)
                return rows
            time.sleep(1)

        return []


def write_application_log_events(
    log_group_name: str,
    correlation_id: str,
    events: List[Dict[str, Any]],
    log_stream_name: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    logger = CloudWatchCorrelationLogger(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )
    return logger.write_events(correlation_id=correlation_id, events=events)
